@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@500;700&family=Inter:wght@400;500;700&display=swap');

:root {
  --primary: #E63946;
  --bg-dark: #111111;
  --bg-card: #1C1C1C;
  --text-main: #FFFFFF;
  --text-muted: #A0A0A0;
  --font-head: 'Oswald', sans-serif;
  --font-body: 'Inter', sans-serif;
  --spacing-sm: 1rem;
  --spacing-md: 2rem;
  --spacing-lg: 4rem;
  --spacing-xl: 6rem;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background-color: var(--bg-dark);
  color: var(--text-main);
  font-family: var(--font-body);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-head);
  text-transform: uppercase;
  font-weight: 700;
  line-height: 1.1;
  letter-spacing: 0.05em;
  margin-bottom: var(--spacing-sm);
}

a {
  color: var(--text-main);
  text-decoration: none;
  transition: color 0.2s ease;
}

a:hover {
  color: var(--primary);
}

img {
  max-width: 100%;
  display: block;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

/* Utilities */
.text-center { text-align: center; }
.text-primary { color: var(--primary); }
.bg-card { background-color: var(--bg-card); }
.py-lg { padding-top: var(--spacing-xl); padding-bottom: var(--spacing-xl); }
.py-md { padding-top: var(--spacing-lg); padding-bottom: var(--spacing-lg); }
.mb-md { margin-bottom: var(--spacing-md); }
.mb-lg { margin-bottom: var(--spacing-lg); }

/* Buttons */
.btn {
  display: inline-block;
  font-family: var(--font-head);
  text-transform: uppercase;
  font-weight: 700;
  padding: 1rem 2rem;
  border: none;
  cursor: pointer;
  letter-spacing: 0.05em;
  transition: all 0.3s ease;
  text-align: center;
}

.btn-primary {
  background-color: var(--primary);
  color: var(--text-main);
}
.btn-primary:hover {
  background-color: #C02E38;
  color: #FFF;
}

.btn-outline {
  background-color: transparent;
  color: var(--text-main);
  border: 2px solid var(--text-main);
}
.btn-outline:hover {
  background-color: var(--text-main);
  color: var(--bg-dark);
}

/* Header & Nav */
.top-bar {
  background-color: var(--primary);
  color: #fff;
  text-align: center;
  padding: 0.5rem;
  font-size: 0.875rem;
  font-family: var(--font-head);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.top-bar a {
  text-decoration: underline;
  margin-left: 0.5rem;
}

header {
  background-color: rgba(17, 17, 17, 0.95);
  position: sticky;
  top: 0;
  z-index: 100;
  border-bottom: 1px solid #333;
}

.nav-container {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 1rem var(--spacing-md);
  max-width: 1400px;
  margin: 0 auto;
}

.logo {
  font-family: var(--font-head);
  font-size: 2rem;
  font-weight: 700;
  color: var(--primary);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.nav-links {
  display: flex;
  gap: 2rem;
  list-style: none;
}

.nav-links a {
  font-family: var(--font-head);
  text-transform: uppercase;
  font-size: 1rem;
  letter-spacing: 0.05em;
}

.utility-nav {
  display: flex;
  gap: 1rem;
}

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-main);
  font-size: 2rem;
  cursor: pointer;
}

/* Hero Section */
.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  background: linear-gradient(rgba(0,0,0,0.6), rgba(0,0,0,0.8)), url('https://images.unsplash.com/photo-1534438327276-14e5300c3a48?q=80&w=1920&auto=format&fit=crop') center/cover no-repeat;
  padding: var(--spacing-md);
}

.hero-content {
  max-width: 800px;
  z-index: 10;
}

.hero h1 {
  font-size: clamp(3rem, 6vw, 5rem);
  text-shadow: 2px 2px 4px rgba(0,0,0,0.5);
  margin-bottom: 1rem;
}

.hero p {
  font-size: 1.25rem;
  margin-bottom: 2rem;
  color: #ddd;
}

.hero-actions {
  display: flex;
  gap: 1rem;
  justify-content: center;
}

/* Grid Layouts */
.grid-2 { display: grid; grid-template-columns: 1fr 1fr; gap: var(--spacing-lg); }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: var(--spacing-md); }
.grid-4 { display: grid; grid-template-columns: repeat(4, 1fr); gap: var(--spacing-md); }

/* Feature / Split Sections */
.split-section {
  display: flex;
  flex-direction: column;
}

@media (min-width: 768px) {
  .split-section { flex-direction: row; align-items: center; gap: 4rem; }
  .split-section > * { flex: 1; }
  .split-reverse { flex-direction: row-reverse; }
}

/* Carousel */
.carousel-wrapper {
  position: relative;
  overflow: hidden;
  max-width: 100%;
}

.carousel-track {
  display: flex;
  transition: transform 0.4s ease-in-out;
}

.carousel-slide {
  min-width: 100%;
  box-sizing: border-box;
}

.carousel-slide img {
  width: 100%;
  height: 60vh;
  object-fit: cover;
}

.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(0,0,0,0.5);
  color: #fff;
  border: none;
  font-size: 2rem;
  padding: 1rem;
  cursor: pointer;
  z-index: 10;
}

.carousel-btn.prev { left: 10px; }
.carousel-btn.next { right: 10px; }

/* Instructor Grid & Filters */
.filter-bar {
  display: flex;
  justify-content: center;
  gap: 1rem;
  flex-wrap: wrap;
  margin-bottom: 2rem;
}

.filter-btn {
  background: transparent;
  color: var(--text-muted);
  border: 1px solid #333;
  padding: 0.5rem 1rem;
  font-family: var(--font-head);
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.2s;
}

.filter-btn.active, .filter-btn:hover {
  background: var(--primary);
  color: #fff;
  border-color: var(--primary);
}

.instructor-card {
  background: var(--bg-card);
  border-radius: 4px;
  overflow: hidden;
  text-align: center;
  transition: transform 0.3s;
}
.instructor-card:hover {
  transform: translateY(-5px);
}
.instructor-card img {
  width: 100%;
  aspect-ratio: 3/4;
  object-fit: cover;
}
.instructor-info {
  padding: 1.5rem;
}
.instructor-info h3 { margin-bottom: 0.5rem; font-size: 1.5rem; }
.instructor-info p { color: var(--text-muted); margin-bottom: 1rem; }

/* FAQ Accordion */
.accordion {
  max-width: 800px;
  margin: 0 auto;
}
.accordion-item {
  border-bottom: 1px solid #333;
}
.accordion-header {
  width: 100%;
  background: none;
  border: none;
  color: var(--text-main);
  font-family: var(--font-head);
  font-size: 1.25rem;
  text-align: left;
  padding: 1.5rem 0;
  cursor: pointer;
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.accordion-header::after {
  content: '+';
  font-size: 1.5rem;
  color: var(--primary);
  transition: transform 0.3s;
}
.accordion-item.active .accordion-header::after {
  transform: rotate(45deg);
}
.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
  color: var(--text-muted);
}
.accordion-item.active .accordion-content {
  max-height: 500px;
}
.accordion-content-inner {
  padding-bottom: 1.5rem;
}

/* Floor vs Treadmill Toggle */
.toggle-wrapper {
  text-align: center;
  margin-bottom: 3rem;
}
.toggle-controls {
  display: inline-flex;
  background: var(--bg-card);
  border-radius: 30px;
  padding: 0.25rem;
}
.toggle-btn {
  background: transparent;
  color: var(--text-muted);
  border: none;
  padding: 0.75rem 2rem;
  font-family: var(--font-head);
  text-transform: uppercase;
  font-size: 1.1rem;
  border-radius: 30px;
  cursor: pointer;
  transition: all 0.3s;
}
.toggle-btn.active {
  background: var(--primary);
  color: #fff;
}
.toggle-content {
  display: none;
  animation: fadeIn 0.4s ease;
}
.toggle-content.active {
  display: block;
}
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Schedule Table */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 2rem;
  background: var(--bg-card);
}
.schedule-table th, .schedule-table td {
  padding: 1rem;
  text-align: left;
  border-bottom: 1px solid #333;
}
.schedule-table th {
  font-family: var(--font-head);
  color: var(--primary);
  text-transform: uppercase;
  font-size: 1.2rem;
}

/* Footer & Newsletter */
.newsletter-section {
  background: var(--primary);
  text-align: center;
}
.newsletter-form {
  display: flex;
  max-width: 500px;
  margin: 1.5rem auto 0;
  position: relative;
}
.newsletter-form input {
  flex: 1;
  padding: 1rem;
  border: none;
  font-family: var(--font-body);
  outline: none;
}
.newsletter-form .btn {
  background: var(--bg-dark);
  color: #fff;
}
.newsletter-msg {
  display: none;
  margin-top: 1rem;
  font-weight: bold;
}

footer {
  background: #0a0a0a;
  padding: 4rem 2rem 2rem;
  border-top: 1px solid #222;
}
.footer-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: 2rem;
  margin-bottom: 3rem;
}
.footer-col h4 {
  color: #fff;
  margin-bottom: 1rem;
  font-size: 1.2rem;
}
.footer-col ul { list-style: none; }
.footer-col li { margin-bottom: 0.5rem; }
.footer-col a { color: var(--text-muted); }
.footer-col a:hover { color: var(--primary); }

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: 2rem;
  border-top: 1px solid #333;
  color: var(--text-muted);
  font-size: 0.875rem;
  flex-wrap: wrap;
  gap: 1rem;
}
.country-select select {
  background: transparent;
  color: #fff;
  border: 1px solid #333;
  padding: 0.5rem;
  font-family: var(--font-body);
}

/* Responsive */
@media (max-width: 768px) {
  .nav-links, .utility-nav { display: none; }
  .mobile-menu-btn { display: block; }
  .grid-2, .grid-3, .grid-4 { grid-template-columns: 1fr; }
  .hero h1 { font-size: 2.5rem; }
  .hero-actions { flex-direction: column; }
  .newsletter-form { flex-direction: column; }
}

.banner-img {
    width: 100%;
    height: 400px;
    object-fit: cover;
}

.stat-number {
    font-size: 4rem;
    font-family: var(--font-head);
    color: var(--primary);
    line-height: 1;
    margin-bottom: 0.5rem;
}

document.addEventListener('DOMContentLoaded', () => {
  // Mobile menu toggle (simple version)
  const mobileMenuBtn = document.querySelector('.mobile-menu-btn');
  const navLinks = document.querySelector('.nav-links');
  if (mobileMenuBtn && navLinks) {
    mobileMenuBtn.addEventListener('click', () => {
      if (navLinks.style.display === 'flex') {
        navLinks.style.display = 'none';
      } else {
        navLinks.style.display = 'flex';
        navLinks.style.flexDirection = 'column';
        navLinks.style.position = 'absolute';
        navLinks.style.top = '100%';
        navLinks.style.left = '0';
        navLinks.style.right = '0';
        navLinks.style.background = 'rgba(17, 17, 17, 0.95)';
        navLinks.style.padding = '1rem';
      }
    });
  }

  // Newsletter Validation
  const newsletterForms = document.querySelectorAll('.newsletter-form');
  newsletterForms.forEach(form => {
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      const input = form.querySelector('input[type="email"]');
      const msg = form.querySelector('.newsletter-msg');
      if (input.value && input.value.includes('@')) {
        msg.style.display = 'block';
        msg.style.color = '#fff';
        msg.textContent = 'Thanks for subscribing! Check your inbox soon.';
        input.value = '';
      } else {
        msg.style.display = 'block';
        msg.style.color = '#ffcccc';
        msg.textContent = 'Please enter a valid email address.';
      }
    });
  });

  // Home Carousel
  const track = document.querySelector('.carousel-track');
  const slides = Array.from(document.querySelectorAll('.carousel-slide'));
  const nextBtn = document.querySelector('.carousel-btn.next');
  const prevBtn = document.querySelector('.carousel-btn.prev');

  if (track && slides.length > 0) {
    let currentIndex = 0;
    let startX = 0;
    let isDragging = false;

    const updateCarousel = () => {
      track.style.transform = `translateX(-${currentIndex * 100}%)`;
    };

    if (nextBtn) {
      nextBtn.addEventListener('click', () => {
        currentIndex = (currentIndex + 1) % slides.length;
        updateCarousel();
      });
    }

    if (prevBtn) {
      prevBtn.addEventListener('click', () => {
        currentIndex = (currentIndex - 1 + slides.length) % slides.length;
        updateCarousel();
      });
    }

    // Touch events for swipe
    track.addEventListener('touchstart', (e) => {
      startX = e.touches[0].clientX;
      isDragging = true;
    });

    track.addEventListener('touchmove', (e) => {
      if (!isDragging) return;
    });

    track.addEventListener('touchend', (e) => {
      if (!isDragging) return;
      isDragging = false;
      const endX = e.changedTouches[0].clientX;
      const diffX = startX - endX;

      if (diffX > 50) {
        currentIndex = (currentIndex + 1) % slides.length;
        updateCarousel();
      } else if (diffX < -50) {
        currentIndex = (currentIndex - 1 + slides.length) % slides.length;
        updateCarousel();
      }
    });
  }

  // FAQ Accordion
  const accordionHeaders = document.querySelectorAll('.accordion-header');
  accordionHeaders.forEach(header => {
    header.addEventListener('click', () => {
      const item = header.parentElement;
      const isActive = item.classList.contains('active');

      // Close all
      document.querySelectorAll('.accordion-item').forEach(accItem => {
        accItem.classList.remove('active');
      });

      // Toggle current
      if (!isActive) {
        item.classList.add('active');
      }
    });
  });

  // Floor vs Treadmill Toggle
  const toggleBtns = document.querySelectorAll('.toggle-btn');
  const toggleContents = document.querySelectorAll('.toggle-content');
  if (toggleBtns.length > 0) {
    toggleBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        const target = btn.dataset.target;

        toggleBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        toggleContents.forEach(content => {
          if (content.id === target) {
            content.classList.add('active');
          } else {
            content.classList.remove('active');
          }
        });
      });
    });
  }

  // Instructor Filtering
  const filterBtns = document.querySelectorAll('.filter-btn');
  const instructorCards = document.querySelectorAll('.instructor-card');
  if (filterBtns.length > 0) {
    filterBtns.forEach(btn => {
      btn.addEventListener('click', () => {
        const filter = btn.dataset.filter;

        filterBtns.forEach(b => b.classList.remove('active'));
        btn.classList.add('active');

        instructorCards.forEach(card => {
          if (filter === 'all' || card.dataset.location === filter) {
            card.style.display = 'block';
          } else {
            card.style.display = 'none';
          }
        });
      });
    });
  }
});
